import os
import torch


class Config:
    """
    Configuration class for the Multi-Label Artwork Classification task.
    Centralizes all hyperparameters, file paths, and model settings.
    """

    # ==========================================
    # Reproducibility
    # ==========================================
    SEED = 42

    # ==========================================
    # File Paths
    # ==========================================
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"

    # Metadata files generated by the metadata script
    TRAIN_CSV = os.path.join(METADATA_DIR, "train.csv")
    VAL_CSV = os.path.join(METADATA_DIR, "val.csv")
    TEST_CSV = os.path.join(METADATA_DIR, "test.csv")

    # Output Directories
    WORKING_DIR = "./working/idea_1"
    SUBMISSION_DIR = "./submission"
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # Model Checkpoint Path
    MODEL_SAVE_PATH = os.path.join(WORKING_DIR, "resnet18_best.pth")

    # ==========================================
    # Model Hyperparameters
    # ==========================================
    MODEL_NAME = "resnet34"
    NUM_CLASSES = 3474
    PRETRAINED = True
    DROPOUT = 0.0  # ResNet usually doesn't use dropout in the backbone, but can be added to head if needed

    # ==========================================
    # Data Hyperparameters
    # ==========================================
    # Image processing
    RESIZE_SIZE = 256
    IMG_SIZE = 224  # Input size for the model (CenterCrop)

    # Normalization (ImageNet standards)
    IMAGENET_MEAN = [0.485, 0.456, 0.406]
    IMAGENET_STD = [0.229, 0.224, 0.225]

    # Dataloader
    BATCH_SIZE = 256  # Adjusted for A100 40GB
    NUM_WORKERS = 12  # Utilizing available vCPUs
    PIN_MEMORY = True

    # ==========================================
    # Training Hyperparameters
    # ==========================================
    EPOCHS = 10
    LEARNING_RATE = 1e-3  # Max LR for OneCycleLR
    WEIGHT_DECAY = 1e-2  # For AdamW

    # Optimization
    USE_AMP = True  # Automatic Mixed Precision
    GRAD_CLIP = 1.0

    # Device configuration
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"

    # ==========================================
    # Inference & Post-processing
    # ==========================================
    # Threshold for converting probabilities to labels
    # This will be optimized on the validation set
    DEFAULT_THRESHOLD = 0.4

    # ==========================================
    # Debugging / Development
    # ==========================================
    DEBUG = False
    DEBUG_SUBSET_SIZE = 5000  # Size of subset if DEBUG is True

    @classmethod
    def setup(cls):
        """
        Creates necessary working and submission directories.
        """
        os.makedirs(cls.WORKING_DIR, exist_ok=True)
        os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)
